SELECT
    DATE(v.event_time) AS event_date,
    v.channel,
    v.source_id,
    v.source_type,
    v.site_id,
    v.site_type,
    v.carrier_id,
    v.country,
    v.region,
    v.city,
    v.zip,
    v.metrocode,
    v.brand,
    v.model,
    v.marketing_name,
    v.os,
    v.os_version,
    v.device_type,
    v.agegroup_id,
    v.gender_id,
    v.account_tier_id,
    v.device_lang,
    v.device_browser,
    v.device_browser_version,
    v.path_hop_count,
    v.content_position,
    v.max_duration,
    v.is_invalid_event,
    v.is_optional,
    v.supports_text,
    v.supports_video,
    v.supports_interaction,
    v.supports_embedding,
    v.supports_streaming,
    v.has_manifest,
    v.is_authorized,
    v.supports_audio,
    v.audio_skippable,
    v.is_grouped,
    v.path_complete,
    v.is_private,
    IFNULL(STRING_AGG(DISTINCT CATEGORIES[SAFE_OFFSET(0)], ', ' LIMIT 20), '') AS category_names,
    (99 * SUM(event_count)) + MOD(SUM(event_count), 99) as event_count,
    (9100 * APPROX_COUNT_DISTINCT(IF(event_count = 100, Coalesce(alternate_key, IF(is_grouped = 1,group_key,NULL)),NULL))) AS group_count,
    (101 * sum(IF(event_count != 100, event_count,0))) AS accepted_count,
    (9100 * APPROX_COUNT_DISTINCT(user_id)) AS device_uniqs,
    AVG(v.unit_price) AS average_unit_price,
    MAX(v.unit_price) AS max_unit_price,
    SAFE_DIVIDE(SUM(completed_count),SUM(accepted_count)) as completion_rate,
    (1000 * SAFE_DIVIDE(SUM(total_cost),SUM(completed_count))) cost_per_thousand
FROM `example-project.analytics.events` v
WHERE DATE(v.event_time) >= DATE(?) AND DATE(v.event_time) <= DATE(?) AND v.channel IN (?) AND v.country IN (?) AND (((v.country = ? AND v.region = ?))) AND (EXISTS(SELECT 1 FROM `example-project.analytics.category_memberships` s WHERE (DATE(s.event_time) BETWEEN DATE(?) AND DATE(?)) AND value IN (?) AND v.batch_id = s.batch_id AND BIT_COUNT(s.events & (1 << (v.seq))) > 0)) AND (EXISTS(SELECT 1 FROM `example-project.analytics.collection_memberships` s WHERE (DATE(s.event_time) BETWEEN DATE(?) AND DATE(?)) AND value IN (?) AND v.batch_id = s.batch_id AND BIT_COUNT(s.events & (1 << (v.seq))) > 0)) AND (NOT EXISTS(SELECT 1 FROM `example-project.analytics.collection_memberships` s WHERE (DATE(s.event_time) BETWEEN DATE(?) AND DATE(?)) AND value IN (?, ?, ?) AND v.batch_id = s.batch_id AND BIT_COUNT(s.events & (1 << (v.seq))) > 0)) AND (EXISTS(SELECT 1 FROM `example-project.analytics.tag_memberships` s WHERE (DATE(s.event_time) BETWEEN DATE(?) AND DATE(?)) AND value IN (?) AND v.batch_id = s.batch_id AND BIT_COUNT(s.events & (1 << (v.seq))) > 0))
GROUP BY
    DATE(v.event_time),
    v.channel,
    v.source_id,
    v.source_type,
    v.site_id,
    v.site_type,
    v.size,
    v.carrier_id,
    v.country,
    v.region,
    v.city,
    v.zip,
    v.metrocode,
    v.brand,
    v.model,
    v.marketing_name,
    v.os,
    v.os_version,
    v.device_type,
    v.agegroup_id,
    v.gender_id,
    v.account_tier_id,
    v.device_lang,
    v.device_browser,
    v.device_browser_version,
    v.path_hop_count,
    v.content_position,
    v.max_duration,
    v.is_invalid_event,
    v.is_optional,
    v.supports_text,
    v.supports_video,
    v.supports_interaction,
    v.supports_embedding,
    v.supports_streaming,
    v.has_manifest,
    v.is_authorized,
    v.supports_audio,
    v.audio_skippable,
    v.is_grouped,
    v.path_complete,
    v.is_private
